### Creates a new Agent (Typed version for SDK).
# @name CreateAgent
POST {{host}}/v1beta/agents
x-goog-api-key: {{api_key}}
Content-Type: application/json
Accept: application/json

{
  "agent_config": {
    "max_total_tokens": "string",
    "model": "string",
    "type": "string"
  },
  "base_agent": "string",
  "base_environment": {
    "env": {},
    "environment_id": "string",
    "network": {
      "allowlist": [
        {
          "domain": "github.com",
          "transform": [
            {
              "Authorization": "Bearer your-token"
            }
          ]
        },
        {
          "domain": "*.googleapis.com"
        }
      ]
    },
    "sources": [
      {}
    ],
    "type": "string"
  },
  "description": "string",
  "id": "string",
  "system_instruction": "string",
  "tools": [
    {
      "type": "string"
    }
  ]
}

## Responses
# default
# Description: Successful operation
# Content-Type: application/json

### Creates a new interaction.
# @name CreateInteraction
POST {{host}}/v1beta/interactions
x-goog-api-key: {{api_key}}
Content-Type: application/json
Accept: application/json, text/event-stream

{
  "agent": "deep-research-pro-preview-12-2025",
  "agent_config": {
    "max_total_tokens": "string",
    "model": "string",
    "type": "string"
  },
  "background": true,
  "continuation_token": "",
  "environment": {
    "env": {},
    "environment_id": "string",
    "network": {
      "allowlist": [
        {
          "domain": "github.com",
          "transform": [
            {
              "Authorization": "Bearer your-token"
            }
          ]
        },
        {
          "domain": "*.googleapis.com"
        }
      ]
    },
    "sources": [
      {}
    ],
    "type": "string"
  },
  "input": {
    "type": "audio",
    "data": "BASE64_ENCODED_AUDIO",
    "mime_type": "audio/wav"
  },
  "labels": {},
  "previous_interaction_id": "string",
  "response_format": {
    "type": "audio",
    "sample_rate": 24000
  },
  "response_mime_type": "string",
  "response_modalities": [
    "text"
  ],
  "safety_settings": [
    {
      "method": "severity",
      "threshold": "block_low_and_above",
      "type": "hate_speech"
    }
  ],
  "service_tier": "flex",
  "store": true,
  "stream": true,
  "system_instruction": "string",
  "tools": [
    {
      "type": "string"
    }
  ],
  "webhook_config": {
    "uris": [
      "string"
    ],
    "user_metadata": {}
  }
}

## Responses
# 200
# Description: Successful operation
# Content-Type: application/json, text/event-stream
# 4XX
# Description: Client Error
# Content-Type: application/json
# 5XX
# Description: Server Error
# Content-Type: application/json
